import { navigate } from "gatsby";
import React, { useCallback, useEffect, useState } from "react";
import type { UserProfile } from "../types";
import { getUserById, updateUser } from "../../../sessionServices/users/usersService";
import { listItinerariesByUser } from "../../../sessionServices/itineraries/itinerariesService";
import { writeAuditLog } from "../../../sessionServices/audit/auditLogsService";
import { ItineraryDetail } from "./ItineraryDetail";
import { useAuth } from "../../auth/AuthContext";
import type { Itinerary } from "../types";
import { RxCaretDown, RxCaretUp } from "react-icons/rx";

interface Props {
  uid: string;
}

type ItineraryWithId = Itinerary & { id: string };

const ROLE_OPTIONS = ["admin", "customer"] as const;
const STATUS_OPTIONS = ["active", "inactive", "blocked"] as const;

const STATUS_BADGE: Record<string, string> = {
  active: "bg-green-100 text-green-700",
  inactive: "bg-gray-100 text-gray-600",
  blocked: "bg-red-100 text-red-700",
};

const ROLE_BADGE: Record<string, string> = {
  admin: "bg-purple-100 text-purple-700",
  customer: "bg-orange-100 text-orange-700",
};

const ITINERARY_STATUS_BADGE: Record<string, string> = {
  draft: "bg-gray-100 text-gray-600",
  in_review: "bg-yellow-100 text-yellow-700",
  approved: "bg-blue-100 text-blue-700",
  shared: "bg-green-100 text-green-700",
  in_follow_up: "bg-purple-100 text-purple-700",
  closed: "bg-red-100 text-red-600",
};

export function UserDetailView({ uid }: Props) {
  const { user: currentUser } = useAuth();
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [itineraries, setItineraries] = useState<ItineraryWithId[]>([]);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [expandedItinerary, setExpandedItinerary] = useState<string | null>(null);

  // Edit form state mirrors profile
  const [form, setForm] = useState({
    fullName: "",
    phoneNumber: "",
    role: "customer" as string,
    status: "active" as string,
    language: "",
  });

  const load = useCallback(async () => {
    const [profileData, itinerariesData] = await Promise.all([
      getUserById(uid),
      listItinerariesByUser(uid),
    ]);
    setProfile(profileData);
    if (profileData) {
      setForm({
        fullName: profileData.fullName,
        phoneNumber: profileData.phoneNumber ?? "",
        role: profileData.role,
        status: profileData.status,
        language: profileData.language ?? "",
      });
    }
    setItineraries(itinerariesData);
    setLoading(false);
  }, [uid]);

  useEffect(() => { load(); }, [load]);

  function startEdit() {
    if (!profile) return;
    setForm({
      fullName: profile.fullName,
      phoneNumber: profile.phoneNumber ?? "",
      role: profile.role,
      status: profile.status,
      language: profile.language ?? "",
    });
    setEditing(true);
    setError(null);
  }

  async function handleSave() {
    if (!currentUser || !profile) return;
    setSaving(true);
    setError(null);
    try {
      await updateUser(uid, {
        fullName: form.fullName,
        phoneNumber: form.phoneNumber || undefined,
        role: form.role as UserProfile["role"],
        status: form.status as UserProfile["status"],
        language: form.language || undefined,
        updatedBy: currentUser.uid,
      });
      await writeAuditLog({
        entityType: "user",
        entityId: uid,
        action: "update",
        after: { fullName: form.fullName, role: form.role, status: form.status },
        performedBy: currentUser.uid,
      });
      setEditing(false);
      load();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Error saving changes.");
    } finally {
      setSaving(false);
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <div className="h-6 w-6 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
      </div>
    );
  }

  if (!profile) {
    return <p className="text-sm text-gray-500">User not found.</p>;
  }

  return (
    <div className="space-y-6">
      {/* Profile card */}
      <div className="rounded-xl bg-white p-6 shadow-sm ring-1 ring-gray-200">
        <div className="mb-4 flex items-center justify-between">
          <h2 className="text-base font-semibold text-gray-900">Profile</h2>
          {!editing && (
            <button
              onClick={startEdit}
              className="rounded-lg border border-gray-300 px-4 py-1.5 text-sm font-medium text-gray-700 hover:bg-gray-100"
            >
              Edit profile
            </button>
          )}
        </div>

        {editing ? (
          <div className="space-y-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <Field label="Full name">
                <input
                  type="text"
                  value={form.fullName}
                  onChange={(e) => setForm((p) => ({ ...p, fullName: e.target.value }))}
                  className={inputClass}
                />
              </Field>
              <Field label="Phone">
                <input
                  type="tel"
                  value={form.phoneNumber}
                  onChange={(e) => setForm((p) => ({ ...p, phoneNumber: e.target.value }))}
                  className={inputClass}
                />
              </Field>
              <Field label="Role">
                <select
                  value={form.role}
                  onChange={(e) => setForm((p) => ({ ...p, role: e.target.value }))}
                  className={inputClass}
                >
                  {ROLE_OPTIONS.map((r) => (
                    <option key={r} value={r}>{r}</option>
                  ))}
                </select>
              </Field>
              <Field label="Status">
                <select
                  value={form.status}
                  onChange={(e) => setForm((p) => ({ ...p, status: e.target.value }))}
                  className={inputClass}
                >
                  {STATUS_OPTIONS.map((s) => (
                    <option key={s} value={s}>{s}</option>
                  ))}
                </select>
              </Field>
              <Field label="Language">
                <input
                  type="text"
                  placeholder="en, fr, es"
                  value={form.language}
                  onChange={(e) => setForm((p) => ({ ...p, language: e.target.value }))}
                  className={inputClass}
                />
              </Field>
            </div>
            {error && (
              <p className="rounded-lg bg-red-50 px-3 py-2 text-sm text-red-600">{error}</p>
            )}
            <div className="flex gap-3">
              <button
                onClick={handleSave}
                disabled={saving}
                className="rounded-lg bg-gray-900 px-5 py-2 text-sm font-medium text-white hover:bg-gray-700 disabled:opacity-60"
              >
                {saving ? "Saving…" : "Save changes"}
              </button>
              <button
                onClick={() => setEditing(false)}
                className="rounded-lg border border-gray-300 px-5 py-2 text-sm font-medium text-gray-700 hover:bg-gray-100"
              >
                Cancel
              </button>
            </div>
          </div>
        ) : (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            <InfoField label="Full name" value={profile.fullName} />
            <InfoField label="Email" value={profile.email} />
            <InfoField label="Phone" value={profile.phoneNumber ?? "—"} />
            <InfoField label="Language" value={profile.language ?? "—"} />
            <div>
              <p className="mb-1 text-xs font-medium text-gray-500">Role</p>
              <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${ROLE_BADGE[profile.role] ?? "bg-gray-100 text-gray-600"}`}>
                {profile.role}
              </span>
            </div>
            <div>
              <p className="mb-1 text-xs font-medium text-gray-500">Status</p>
              <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${STATUS_BADGE[profile.status]}`}>
                {profile.status}
              </span>
            </div>
            <InfoField label="UID" value={profile.uid} mono />
            <InfoField label="Created by" value={profile.createdBy} mono />
          </div>
        )}
      </div>

      {/* Itineraries */}
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-gray-700">
            Itineraries ({itineraries.length})
          </h2>
          <button
            onClick={() => navigate(`/admin/itineraries/new`)}
            className="rounded-lg bg-gray-900 px-3 py-1.5 text-xs font-medium text-white hover:bg-gray-700"
          >
            + New itinerary
          </button>
        </div>

        {itineraries.length === 0 ? (
          <div className="rounded-xl bg-white py-10 text-center ring-1 ring-gray-200">
            <p className="text-sm text-gray-400">No itineraries yet for this customer.</p>
          </div>
        ) : (
          itineraries.map((it) => (
            <div key={it.id} className="overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-gray-200">
              {/* Itinerary header */}
              <div className="flex items-center justify-between px-5 py-4">
                <button
                  onClick={() => setExpandedItinerary(expandedItinerary === it.id ? null : it.id)}
                  className="flex flex-1 items-center gap-3 text-left"
                >
                  {/* <svg
                    className={`h-4 w-4 shrink-0 text-gray-400 transition-transform ${expandedItinerary === it.id ? "rotate-180" : ""}`}
                    fill="none" stroke="currentColor" viewBox="0 0 24 24"
                  >
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                  </svg> */}
                  {expandedItinerary === it.id ? (<RxCaretUp  />) : (<RxCaretDown />
)}
                  {/* <RxCaretDown /> */}
                  <div className="space-y-0.5">
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-semibold text-gray-900">{it.title}</span>
                      <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${ITINERARY_STATUS_BADGE[it.status] ?? "bg-gray-100 text-gray-600"}`}>
                        {it.status.replace("_", " ")}
                      </span>
                    </div>
                    <p className="text-xs text-gray-500">
                      {it.destinationCities.join(", ") || "—"} &nbsp;·&nbsp;
                      {formatDate(it.startDate)} – {formatDate(it.endDate)} &nbsp;·&nbsp;
                      {it.travelerCount} traveler{it.travelerCount !== 1 ? "s" : ""}
                    </p>
                  </div>
                </button>
                <button
                  onClick={() => navigate(`/admin/itineraries/${it.id}/edit`)}
                  className="ml-4 shrink-0 rounded-lg border border-gray-200 px-3 py-1.5 text-xs font-medium text-gray-600 hover:bg-gray-100"
                >
                  Edit details
                </button>
              </div>

              {/* Expanded: full itinerary management */}
              {expandedItinerary === it.id && (
                <div className="border-t border-gray-100 px-5 py-4">
                  <ItineraryDetail itineraryId={it.id} />
                </div>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
}

function InfoField({ label, value, mono }: { label: string; value: string; mono?: boolean }) {
  return (
    <div>
      <p className="mb-1 text-xs font-medium text-gray-500">{label}</p>
      <p className={`text-sm text-gray-900 ${mono ? "font-mono text-xs text-gray-500" : ""}`}>
        {value}
      </p>
    </div>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div>
      <label className="mb-1 block text-sm font-medium text-gray-700">{label}</label>
      {children}
    </div>
  );
}

function formatDate(ts: unknown): string {
  try {
    return (ts as { toDate: () => Date }).toDate().toLocaleDateString("en-CA");
  } catch {
    return "—";
  }
}

const inputClass =
  "block w-full rounded-lg border border-gray-300 px-3 py-2 text-sm text-gray-900 focus:border-gray-800 focus:outline-none focus:ring-1 focus:ring-gray-800";
